/** The bridge the runtime speaks through: generic protocol in, typed store out. */
class LoyaltyStoreResolver(
    private val store: LoyaltyStore,
    model: Model,
) : StateResolver {
    private val questions = LoyaltyStoreQuestions(model)

    override fun begin(kind: WorkKind): UnitOfWork = store.begin(kind)

    override fun fetchByKeys(shape: String, keys: List<StoreKey>): List<Row> = when (shape) {
        "Member" -> store.members(keys).map { it.toRow() }
        "DuesPayment" -> store.duesPayments(keys).map { it.toRow() }
        "Purchase" -> store.purchases(keys).map { it.toRow() }
        "ThankYouNote" -> store.thankYouNotes(keys).map { it.toRow() }
        "Enrollment" -> store.enrollments(keys).map { it.toRow() }
        "SafetyWaiver" -> store.safetyWaivers(keys).map { it.toRow() }
        "OrientationRecord" -> store.orientationRecords(keys).map { it.toRow() }
        "Keycard" -> store.keycards(keys).map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchAll(shape: String): List<Row> = when (shape) {
        "Member" -> store.allMembers().map { it.toRow() }
        "DuesPayment" -> store.allDuesPayments().map { it.toRow() }
        "Purchase" -> store.allPurchases().map { it.toRow() }
        "ThankYouNote" -> store.allThankYouNotes().map { it.toRow() }
        "Enrollment" -> store.allEnrollments().map { it.toRow() }
        "SafetyWaiver" -> store.allSafetyWaivers().map { it.toRow() }
        "OrientationRecord" -> store.allOrientationRecords().map { it.toRow() }
        "Keycard" -> store.allKeycards().map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchReferencingAny(shape: String, field: String, targets: List<Ref.Persisted>): List<Row> = when {
        shape == "Member" && field == "referrer" -> store.membersByReferrers(targets).map { it.toRow() }
        shape == "DuesPayment" && field == "member" -> store.duesPaymentsByMembers(targets).map { it.toRow() }
        shape == "Purchase" && field == "member" -> store.purchasesByMembers(targets).map { it.toRow() }
        shape == "ThankYouNote" && field == "purchase" -> store.thankYouNotesByPurchases(targets).map { it.toRow() }
        shape == "Enrollment" && field == "member" -> store.enrollmentsByMembers(targets).map { it.toRow() }
        shape == "SafetyWaiver" && field == "member" -> store.safetyWaiversByMembers(targets).map { it.toRow() }
        shape == "OrientationRecord" && field == "member" -> store.orientationRecordsByMembers(targets).map { it.toRow() }
        shape == "Keycard" && field == "member" -> store.keycardsByMembers(targets).map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchCandidates(shape: String, filter: QF): List<Row> {
        if (shape == "Purchase")
            questions.qualifiedPurchaseCandidates.match(filter)?.let { h -> return store.qualifiedPurchaseCandidates().map { it.toRow() } }
        if (shape == "Purchase")
            questions.vipPurchaseCandidates.match(filter)?.let { h -> return store.vipPurchaseCandidates().map { it.toRow() } }
        if (shape == "Member")
            questions.certifiedMemberCandidates.match(filter)?.let { h -> return store.certifiedMemberCandidates().map { it.toRow() } }
        if (shape == "Purchase")
            questions.thankVipCandidates.match(filter)?.let { h -> return store.thankVipCandidates().map { it.toRow() } }
        if (shape == "Member")
            questions.issueKeycardCandidates.match(filter)?.let { h -> return store.issueKeycardCandidates().map { it.toRow() } }
        if (shape == "Purchase")
            questions.never2Candidates.match(filter)?.let { h -> return store.never2Candidates().map { it.toRow() } }
        return fetchAll(shape) // unrecognized filters fall back to the scan floor
    }

    override fun fetchCaptures(instance: Ref.Persisted, refinement: String): Map<String, Any?>? = when (refinement) {
        else -> null
    }
}

